#!/usr/bin/env python
"""
Weekly capture of CFB Victory Model forecasts, before the games are played.

WHY THIS EXISTS
---------------
The report's "Chance of Victory" column is overwritten with the realised result
once a game finishes. Across 2019-2025 that destroyed every pre-game probability
the model ever produced - no Brier score, no calibration curve, ever. This script
freezes the forecast each week so 2026 becomes the first gradable season.

HOW IT WORKS
------------
Loads the published Power BI report as a normal browser would, sets the Team and
Year slicers, and reads the rendered table. No API replay, no header spoofing -
it is exactly what a visitor's browser does, which is what the report was
published for. One report session per run.

USAGE
-----
  python weekly_capture.py                     # default: Baylor, 2026
  python weekly_capture.py --team "Texas Tech"
  python weekly_capture.py --teams Baylor TCU "Iowa State"
  python weekly_capture.py --headed            # watch it work

Output: data/weekly_snapshots/<YYYY-MM-DD>_<team>.csv  (one file per run)
        data/weekly_forecast_log.csv                   (append-only, all runs)

Idempotent per day: re-running for the same team+date overwrites that snapshot
and de-duplicates the log, so a retry after a failure is safe.
"""
from __future__ import annotations
import argparse, csv, datetime as dt, sys, time
from pathlib import Path

from playwright.sync_api import sync_playwright, TimeoutError as PWTimeout

REPORT = ("https://app.powerbi.com/view?r=eyJrIjoiNmU2YzY2YTktZTA1NC00NDA2LTgyZGItYjY0"
          "ZGNiNTJjMzYyIiwidCI6ImQ2ZjAwYjk0LTgxYjYtNDBkMS05ZTQwLTk1OTFlOWYxYjRkYyJ9"
          "&pageName=fe8c0d478504c7c16beb")
ROOT = Path(__file__).resolve().parent
SNAP = ROOT / "data" / "weekly_snapshots"
LOG  = ROOT / "data" / "weekly_forecast_log.csv"

FIELDS = ["captured_at","season","team","week","game_id","opponent","opp_plus_minus",
          "opp_model_rank","venue","exp_pts","opp_exp_pts","win_prob","opp_win_prob",
          "actual_pts","opp_actual_pts"]

# --- JS run inside the page -------------------------------------------------
JS_SET_SLICER = """
([title, value]) => {
  const vis = [...document.querySelectorAll('.visualContainer')]
      .find(v => (v.innerText||'').trim().startsWith(title));
  if (!vis) return {ok:false, err:'slicer "'+title+'" not found'};
  const dd = vis.querySelector('.slicer-dropdown-menu');
  if (!dd) return {ok:false, err:'no dropdown in "'+title+'"'};
  const r = dd.getBoundingClientRect();
  ['pointerdown','mousedown','pointerup','mouseup','click'].forEach(t =>
    dd.dispatchEvent(new MouseEvent(t,{bubbles:true,cancelable:true,view:window,
      clientX:r.left+r.width/2, clientY:r.top+r.height/2})));
  return {ok:true};
}
"""

JS_SEARCH = """
(value) => {
  const inp = [...document.querySelectorAll('input.searchInput')]
      .find(i => i.offsetWidth || i.offsetHeight);
  if (!inp) return {ok:false, err:'no visible search box'};
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value').set;
  inp.focus(); setter.call(inp, value);
  inp.dispatchEvent(new Event('input',{bubbles:true}));
  inp.dispatchEvent(new Event('change',{bubbles:true}));
  // Power BI's slicer search filters on keyup, not input - without this the
  // list never narrows and the option stays off-screen in the virtual list.
  inp.dispatchEvent(new KeyboardEvent('keydown',{bubbles:true, key:value.slice(-1)}));
  inp.dispatchEvent(new KeyboardEvent('keyup',  {bubbles:true, key:value.slice(-1)}));
  return {ok:true};
}
"""

JS_LIST = r"""
() => [...document.querySelectorAll('[role="option"], .slicerItemContainer')]
        .map(e => (e.getAttribute('aria-label')||e.innerText||'')
                    .replace(/ /g,' ').replace(/\s+/g,' ').trim())
        .filter(Boolean)
"""

JS_HAS_SEARCH = """
() => !![...document.querySelectorAll('input.searchInput')]
          .find(i => i.offsetWidth || i.offsetHeight)
"""

JS_PICK = """
(value) => {
  const els = [...document.querySelectorAll('[role="option"], .slicerItemContainer')];
  const el = els.find(e => ((e.getAttribute('aria-label')||e.innerText||'').trim() === value));
  if (!el) return {ok:false, err:'option "'+value+'" not in list',
                   sawInstead: els.slice(0,6).map(e=>(e.innerText||'').trim())};
  const r = el.getBoundingClientRect();
  ['pointerdown','mousedown','pointerup','mouseup','click'].forEach(t =>
    el.dispatchEvent(new MouseEvent(t,{bubbles:true,cancelable:true,view:window,
      clientX:r.left+r.width/2, clientY:r.top+r.height/2})));
  return {ok:true};
}
"""

JS_READ = r"""
() => {
  const grids = [...document.querySelectorAll('[role="grid"]')];
  if (grids.length < 2) return {ok:false, err:'grids not rendered ('+grids.length+')'};
  const cellText = c => {
    const al = c.getAttribute('aria-label');
    const raw = (al !== null && al !== '' ? al : (c.innerText||''));
    // Power BI emits non-breaking spaces inside team names ("Iowa State").
    // Left alone these silently break joins against any other data source.
    return raw.replace(/ /g,' ').replace(/\s+/g,' ').trim();
  };
  const readGrid = g => [...g.querySelectorAll('[role="row"]')]
      .map(r => [...r.querySelectorAll('[role="gridcell"],[role="rowheader"]')].map(cellText));

