                print(f"    {title} attempt {i+1} failed, retrying...")
            page.keyboard.press("Escape")
            page.wait_for_timeout(2500)
    raise last


def _set_slicer_once(page, title: str, value: str, verbose=True):
    """Set one slicer using Playwright's real input pipeline.

    Synthetic MouseEvents dispatched via evaluate() do not carry focus/blur and
    are not trusted events, which leaves this Angular app in half-applied states
    (dropdown open, stale search text, slicer header reading "(Not yet applied)").
    Native click/fill/keyboard drive the same path a person does, so the app
    settles correctly between steps.
    """
    if page.evaluate(JS_STATE).get(title) == value:
        if verbose: print(f"    {title} already = {value}, skipping")
        return

    vis = page.locator(".visualContainer").filter(
        has=page.locator(f'.slicer-header-text:text-is("{title}")')).first
    vis.locator(".slicer-dropdown-menu").click(timeout=20_000)

    # NB: page.locator("input.searchInput").locator("visible=true") matches
    # nothing - "visible=true" is a selector-engine clause, not a chainable
    # locator. Getting this wrong skips the search silently and the virtual
    # list never narrows.
    search = page.locator("input.searchInput:visible").first
    if search.count() and search.is_visible():
        # fill() sets .value and fires a synthetic "input" event, which this
        # slicer ignores - it filters on real key events. keyboard.type()
        # produces genuine keydown/keypress/keyup per character.
        search.click()
        page.keyboard.press("ControlOrMeta+a")
        page.keyboard.press("Delete")       # clear residue from a previous team
        page.wait_for_timeout(500)
        page.keyboard.type(value, delay=60)
        page.wait_for_timeout(1800)

    # The options are <div role="option" class="slicerItemContainer"> with no
    # aria-label, and they sit outside any listbox - so Playwright's a11y tree
    # never exposes them and get_by_role("option") always times out. Match on
    # normalised text in the page (handles the non-breaking spaces too), then
    # click by index.
    idx = None
    for _ in range(20):
        opts = page.evaluate(JS_LIST)
        if value in opts:
            idx = opts.index(value)
            break
        page.wait_for_timeout(500)
