            except Exception as e:
                print(f"    FAILED: {e}"); fails.append(t); continue
            if not rows:
                print(f"    FAILED: no rows"); fails.append(t); continue
            dest, total = write_out(rows, t)
            unplayed = sum(1 for r in rows if r["actual_pts"] is None)
            print(f"    {len(rows)} games ({unplayed} still unplayed) -> {dest.name}")
            print(f"    log now {total} rows")
        b.close()

